#!/usr/bin/env bash
# Fails if a function the SBF compiler flagged for an oversized stack frame ("Stack offset of N
# exceeded max offset of 4096") is linked into a program. The compiler checks every function it
# generates, including dead ones that the linker then drops, so the warning alone is not a fault:
# a flagged function only matters if it survives into the .so. Today the only flagged function is
# primitive-types' U512::overflowing_pow (generated by uint's construct_uint!, never called), and
# no program links it.
# Usage: scripts/ci/sbf-stack.sh <anchor build log> <target dir>
set -euo pipefail
log=$1 target=$2
objdump=$(ls -d "$HOME"/.cache/solana/v*/platform-tools/llvm/bin/llvm-objdump 2>/dev/null | sort -V | tail -1)
[ -x "$objdump" ] || { echo "llvm-objdump from platform-tools not found" >&2; exit 2; }
flagged=$(grep -oE 'Function [^ ]+ Stack offset of [0-9]+ exceeded' "$log" | awk '{print $2}' | sort -u || true)
sos=$(ls "$target"/sbpf-solana-solana/release/*.so "$target"/sbf-solana-solana/release/*.so 2>/dev/null || true)
[ -n "$sos" ] || { echo "no unstripped .so under $target" >&2; exit 2; }
fail=0
for f in $flagged; do
  hits=""
  for so in $sos; do
    syms=$("$objdump" -t "$so")
    if grep -qF "$f" <<<"$syms"; then hits="$hits $(basename "$so")"; fi
  done
  if [ -n "$hits" ]; then echo "LINKED (can fault at runtime): $f in$hits"; fail=1
  else echo "flagged but not linked into any program: $f"; fi
done
[ -n "$flagged" ] || echo "no oversized stack frames flagged"
exit $fail
